package com.gameaggregator.buildservice.config;import java.net.URI;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import software.amazon.awssdk.auth.credentials.*;import software.amazon.awssdk.regions.Region;import software.amazon.awssdk.services.s3.*;import software.amazon.awssdk.services.s3.presigner.S3Presigner;@Configuration public class StorageConfig{@Bean AwsBasicCredentials credentials(@Value("${storage.access-key}")String a,@Value("${storage.secret-key}")String s){return AwsBasicCredentials.create(a,s);}@Bean S3Presigner presigner(AwsBasicCredentials c,@Value("${storage.endpoint}")URI e,@Value("${storage.region}")String r){return S3Presigner.builder().credentialsProvider(StaticCredentialsProvider.create(c)).region(Region.of(r)).endpointOverride(e).serviceConfiguration(S3Configuration.builder().pathStyleAccessEnabled(true).build()).build();}@Bean S3Client s3(AwsBasicCredentials c,@Value("${storage.endpoint}")URI e,@Value("${storage.region}")String r){return S3Client.builder().credentialsProvider(StaticCredentialsProvider.create(c)).region(Region.of(r)).endpointOverride(e).forcePathStyle(true).build();}}